KG42.register("rules-12563bb7fa310f532ced8f16",{"id":"03-bilateral_p2p::v141-c-R003","paper":"03-bilateral_p2p","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"Agents must generate energy or buy it upstream to meet their local loads and downstream obligations from the forward market. Scope: Real-time bilateral contract market; agents' local loads and downstream obligations from the forward market. Prosumers must satisfy their local loads and downstream energy contracts through local generation and/or upstream contracts. Scope: Prosumer fulfillment of local loads and downstream energy contracts in the bilateral contract network. Downstream energy contracts sold by a supplier must be matched by upstream energy contracts it has bought. Scope: Supplier intermediaries' downstream energy obligations in the bilateral contract network. Generators must satisfy their downstream contracts through local generation and/or upstream contracts. Scope: Generators' fulfillment of downstream contracts in the bilateral contract network.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Generators' fulfillment of downstream contracts in the bilateral contract network. | Prosumer fulfillment of local loads and downstream energy contracts in the bilateral contract network. | Real-time bilateral contract market; agents' local loads and downstream obligations from the forward market. | Supplier intermediaries' downstream energy obligations in the bilateral contract network.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e10","v141-b-g01-e24","v141-b-g01-e31","v141-b-g01-e33","v141-b-g01-e35"]},"x":[{"variable_id":"v141-c-R003-x-YFi","symbol":"Y_{Fi}","meaning":"Agent i's selected upstream (bought) forward-market energy contracts; enters the balance obligations through its cardinality |Y_{Fi}|.","kind":"operational","domain":"Y_{Fi} \\subseteq X_{F} (subset of the forward-market contract set)","unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e14","v141-b-g01-e24"]},{"variable_id":"v141-c-R003-x-YRi","symbol":"Y_{Ri}","meaning":"Agent i's selected upstream (bought) real-time-market energy contracts; enters the balance obligations through its cardinality |Y_{Ri}|.","kind":"operational","domain":"Y_{Ri} \\subseteq X_{R} (subset of the real-time contract set)","unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e14","v141-b-g01-e24"]},{"variable_id":"v141-c-R003-x-ZFi","symbol":"Z_{Fi}","meaning":"Agent i's selected downstream (sold) forward-market energy contracts; enters the balance obligations through its cardinality |Z_{Fi}|.","kind":"operational","domain":"Z_{Fi} \\subseteq X_{F} (subset of the forward-market contract set)","unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e14","v141-b-g01-e24"]},{"variable_id":"v141-c-R003-x-ZRi","symbol":"Z_{Ri}","meaning":"Agent i's selected downstream (sold) real-time-market energy contracts; enters the balance obligations through its cardinality |Z_{Ri}|.","kind":"operational","domain":"Z_{Ri} \\subseteq X_{R} (subset of the real-time contract set)","unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e02","v141-b-g01-e14","v141-b-g01-e24"]}],"theta":[{"parameter_id":"v141-c-R003-T001","symbol":"d_{ri}","meaning":"Prosumer i's net (inflexible) demand in the real-time market, normalised by the energy per contract; d_{ri} \u003c 0 corresponds to net generation. Known (fixed) in the real-time market; treated as a random variable in the forward market.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e24"]},{"parameter_id":"v141-c-R003-T002","symbol":"\\bar{g}_i","meaning":"Generator i's maximum generation capacity; used as the upper bound on the generator's net dispatched quantity in the balance condition.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e35"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Agents must generate energy or buy it upstream to meet their local loads and downstream obligations from the forward market. Scope: Real-time bilateral contract market; agents' local loads and downstream obligations from the forward market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e10","v141-b-g01-e33"]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"Prosumers must satisfy their local loads and downstream energy contracts through local generation and/or upstream contracts. Scope: Prosumer fulfillment of local loads and downstream energy contracts in the bilateral contract network.","expression":"\\forall i \\in P: |Y_{Ri}| + |Y_{Fi}| - |Z_{Ri}| - |Z_{Fi}| \\geq d_{ri}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R003-x-YFi","v141-c-R003-x-YRi","v141-c-R003-x-ZFi","v141-c-R003-x-ZRi"],"parameter_refs":["v141-c-R003-T001"],"evidence_ids":["v141-b-g01-e24","v141-b-g01-e25"]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"core","statement":"Downstream energy contracts sold by a supplier must be matched by upstream energy contracts it has bought. Scope: Supplier intermediaries' downstream energy obligations in the bilateral contract network.","expression":"\\forall i \\in S: |Y_{Ri}| + |Y_{Fi}| \\geq |Z_{Ri}| + |Z_{Fi}|","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R003-x-YFi","v141-c-R003-x-YRi","v141-c-R003-x-ZFi","v141-c-R003-x-ZRi"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e31","v141-b-g01-e32","v141-b-g01-e33"]},{"constraint_id":"v141-c-R003-C004","kind":"mathematical","role":"core","statement":"Generators must satisfy their downstream contracts through local generation and/or upstream contracts. Scope: Generators' fulfillment of downstream contracts in the bilateral contract network.","expression":"\\forall i \\in G: 0 \\leq |Z_{Ri}| + |Z_{Fi}| - |Y_{Ri}| - |Y_{Fi}| \\leq \\bar{g}_i","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R003-x-YFi","v141-c-R003-x-YRi","v141-c-R003-x-ZFi","v141-c-R003-x-ZRi"],"parameter_refs":["v141-c-R003-T002"],"evidence_ids":["v141-b-g01-e35","v141-b-g01-e36"]}],"pi":[{"evidence_id":"v141-b-g01-e10","location":{"location_id":"src-4a31f0141b-p03-c2r1__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. Contract Networks for Energy Trading","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 10, NO. 2, MARCH 2019 ly A forward market and real-time market","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"A forward market and real-time market are introduced for each energy trading interval during the day (e.g., each hour). In the forward market, agents buy and sell energy contracts based on their expectations of the real-time energy price and their net demand. In the real-time market, loads and renewable generation are no longer uncertain. The agents must generate energy, or buy it upstream, to meet their local loads and downstream obligations from the forward market. The proposed market design operates on the tertiary power system control layer, which is used to coordinate energy flows on a relatively slow time-scale (e.g., one hour intervals). Lower level primary and secondary control layers operating at faster time-scales will still be necessary to maintain power quality and stability [30]. In particular, the lower level control layers need to maintain supply-demand balance when there are renewable generation or load variations which occur within individual trading intervals."},{"evidence_id":"v141-b-g01-e24","location":{"location_id":"src-4a31f0141b-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"Let P ⊆A be the set of prosumers. The prosumers ts, may have inﬂexible loads, ﬂexible loads and/or r","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Let P ⊆ A be the set of prosumers. The prosumers may have inflexible loads, flexible loads and/or renewable sources. The prosumers must ensure their local loads and downstream energy contracts are satisfied by local generation and/or upstream contracts. In the real-time market, prosumer i knows its net demand d_ri ∈ Z (d_ri \u003c 0 corresponds to net generation). Note that d_ri is normalised by the energy per contract. The prosumer receives utility α_fi ≥ 0 for each unit of energy above its net demand, up to its flexible load limit d̄_fi ∈ Z_≥0. Note that any utility function with diminishing returns can be used while maintaining full substitutability."},{"evidence_id":"v141-b-g01-e31","location":{"location_id":"src-4a31f0141b-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"⎧ ha ⎪⎨ αﬁ t′ﬁ−t + αﬁ(t −tsi) ge , t \u003c t′ﬁ, αﬁ(t) = t′ﬁ−tsi ⎪⎩ 0, otherwise, t′ﬁ= tﬁ−Dﬁ(t) . dﬁ B. S","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Let S ⊆ A be the set of suppliers. Suppliers act as intermediaries, buying and selling energy from other agents. The downstream energy contracts sold by a supplier must be matched by upstream energy contracts it has bought. It is assumed supplier i incurs linear transaction costs for energy contracts it buys, modelled by a coefficient c_t1i ≥ 0."},{"evidence_id":"v141-b-g01-e33","location":{"location_id":"src-4a31f0141b-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"r’s downstream real-time energy contracts will be available at es a price of pRi ≥0, which is treate","equation_id":"(11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In the forward market, the supplier assumes upstream and downstream real-time energy contracts will be available at a price of p_Ri ≥ 0, which is treated as a random variable. Real-time upstream contracts will be bought to balance the supplier's downstream obligations from the forward market. Therefore, supplier i's preferences to maximise its expected utility in the real-time market are described by the following forward market utility function, UFi(YFi, ZFi) = Σ_{(ω,pω)∈ZFi} pω − Σ_{(φ,pφ)∈YFi} pφ + E[pRi](|YFi| − |ZFi|) − ct1i(|YFi| + [|ZFi| − |YFi|]^+). (11)"},{"evidence_id":"v141-b-g01-e35","location":{"location_id":"src-4a31f0141b-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"C. Generatorsbe if Let G ⊆A be the set of generators. The generators have if traditional fuel-based ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Let G ⊆ A be the set of generators. The generators have traditional fuel-based sources. The generators must ensure their downstream contracts are satisfied by local generation and/or upstream contracts. Traditional generators with fuel-based sources are often modelled as having increasing marginal costs [33]–[38]. This is suitable for two standard situations: 1) a single generation unit with increasing costs due to increased marginal fuel consumption at higher output powers and 2) multiple generation units, which are dispatched from lowest marginal cost to highest marginal cost. In this paper, a quadratic cost function is adopted, with linear and quadratic coefficients c_g1i, c_g2i ≥ 0 [36]. Note that any function with constant or increasing marginal costs can be used while maintaining full substitutability. However, decreasing marginal costs (economies of scale) are restricted. Generator i has a maximum generation capacity ḡ_i."},{"evidence_id":"v141-b-g01-e02","location":{"location_id":"src-4a31f0141b-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"as β Element of {0, 1, 2} d- p Price adjustment increment to κ(·) Selected contracts of an arrangeme","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"| · | Number of elements of a set; [ · ]^+ max{ · , 0}; +1{·} Indicator function for the specified condition; κ(·) Selected contracts of an arrangement; τ(·) Underlying trades for a set of contracts; Ψ*_m Selected trades at a competitive equilibrium; Ω_m Trades in market m; Ω^B_mi Agent i's potential upstream trades; Ω^S_mi Agent i's potential downstream trades; A Set of agents; a(·) Set of agents associated with a set of contracts; b(·) Buyer of a trade or contract; s(·) Seller of a trade or contract; X_m Set of contracts in market m; X_mi Agent i's contracts in market m; Y_m Set of upstream contracts in market m; Y_mi Agent i's upstream contracts; Y*_mi Agent i's selected upstream contracts; Z Set of integers; Z_m Set of downstream contracts in market m; Z_mi Agent i's downstream contracts; Z*_mi Agent i's selected downstream contracts."},{"evidence_id":"v141-b-g01-e04","location":{"location_id":"src-4a31f0141b-p01-c2r3__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"ng mi( ) g ket c′y Net upstream trades ce- c′z Net downstream trades nt cg1i Generator i’s linear co","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"α_fi Prosumer i's flexible load utility; α̲_fi Initial α_fi for a time-coupled flexible load; ᾱ_fi Final α_fi for a time-coupled flexible load; d_fi Prosumer i's net flexible demand; d'_fi d_fi, adjusted for the time-coupled flexible load; d̄_fi Prosumer i's flexible load power limit; D_fi(t) Remaining time-coupled flexible load; d_ri Prosumer i's net inflexible demand; d'_ri d_ri, adjusted for the time-coupled flexible load; σ_d_ri Standard deviation of prosumer i's net demand; σ_p_Ri Standard deviation of the real-time energy price; c_g1i Generator i's linear cost coefficient; c_g2i Generator i's quadratic cost coefficient; c_t1i Supplier i's linear cost coefficient; k^ra_di Net demand risk-aversion coefficient; k^ra_pi Energy price risk-aversion coefficient; r_i Prosumer i's risk-aversion exponent; g_i Generator i's unconstrained optimal output; ḡ_i Generator i's maximum capacity; c'_y Net upstream trades; c'_z Net downstream trades; G Set of generator agents; P Set of prosumer agents; S Set of supplier agents; R Set of real numbers; E[ · ] Expectation operator."},{"evidence_id":"v141-b-g01-e14","location":{"location_id":"src-4a31f0141b-p03-c2r3__v141-a-M01-matching","page":3,"printed_page":null,"section":"II. Contract Networks for Energy Trading","anchor_text":"p y p II (ω, pω), where ω ∈ m is the underlying trade and pω is hin the price speciﬁed by the contra","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Each trade ω has a buyer b(ω) ∈ A and a seller s(ω) ∈ A. These are also the buyer and seller for each contract involving ω, i.e., for contract x = (ω, p_ω) we denote its buyer b(x) := b(ω) and seller s(x) := s(ω). The agents involved with a set of contracts X'_m ⊆ X_m are given by a(X'_m) := {∪_{x∈X'_m}b(x), s(x)}. Agent i has upstream contracts Y_mi := {y ∈ X_m|i = b(y)}, and downstream contracts Z_mi := {z ∈ X_m|i = s(x)}."},{"evidence_id":"v141-b-g01-e25","location":{"location_id":"src-4a31f0141b-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"Let P ⊆A be the set of prosumers. The prosumers ts, may have inﬂexible loads, ﬂexible loads and/or r","equation_id":"(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"URi(YRi, ZRi) = Σ_{(ω,pω)∈ZRi∪ZFi} pω − Σ_{(φ,pφ)∈YRi∪YFi} pφ + αfi min{d_fi, |YRi| + |YFi| − |ZRi| − |ZFi| − dri} if |YRi| + |YFi| − |ZRi| − |ZFi| ≥ dri, −∞, otherwise. (7)"},{"evidence_id":"v141-b-g01-e32","location":{"location_id":"src-4a31f0141b-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 10, NO. 2, MARCH 2019 nd real-time market, supplier i’s prefer","equation_id":"(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In the real-time market, supplier i's preferences are described by a utility function, URi(YRi, ZRi) = Σ_{(ω,pω)∈ZRi∪ZFi} pω − Σ_{(φ,pφ)∈YRi∪YFi} pφ − ct1i(|YRi| + |YFi|), if |YRi| + |YFi| ≥ |ZRi| + |ZFi|, −∞, otherwise. (10)"},{"evidence_id":"v141-b-g01-e36","location":{"location_id":"src-4a31f0141b-p05-c2r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Agent Preferences and Contract Selection","anchor_text":"has a maximum generation capacity gi. In the real-time market, generator i’s preferences are describ","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"In the real-time market, generator i's preferences are described by a utility function, URi(YRi, ZRi) = Σ_{(ω,pω)∈ZRi∪ZFi} pω − Σ_{(φ,pφ)∈YRi∪YFi} pφ − cg1i[|ZRi| + |ZFi| − |YRi| − |YFi|]^+ − cg2i([|ZRi| + |ZFi| − |YRi| − |YFi|]^+)^2, if ḡ_i ≥ |ZRi| + |ZFi| − |YRi| − |YFi| ≥ 0, −∞, otherwise. (12)"}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-participation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e10","quote":"In the real-time market, loads and renewable generation are no longer uncertain. The agents must generate energy, or buy it upstream, to meet their local loads and downstream obligations from the forward market."},{"evidence_id":"v141-b-g01-e33","quote":"Real-time upstream contracts will be bought to balance the supplier's downstream obligations from the forward market."}],[{"evidence_id":"v141-b-g01-e24","quote":"The prosumers must ensure their local loads and downstream energy contracts are satisfied by local generation and/or upstream contracts."}],[{"evidence_id":"v141-b-g01-e31","quote":"The downstream energy contracts sold by a supplier must be matched by upstream energy contracts it has bought."}],[{"evidence_id":"v141-b-g01-e35","quote":"The generators must ensure their downstream contracts are satisfied by local generation and/or upstream contracts."}]],"C2_formalization":{"graph_sha256":"59338976f57a0ea7dec09397656ce8a1f9188ae3ba4b8035b7e835534356d960","applicability":"formalized","reason":"Rule v141-c-R003 (execution.energy_trade) is the energy-balance / trade-execution stage of mechanism v141-a-M01 and owns the clearing lead. Frozen graph is V={execution.energy_trade}, E={}. Three of the four C.1 phi entries (C002 prosumer, C003 supplier, C004 generator) receive faithful source transcriptions of the balance conditions that the source itself writes as the finite-domain constraints of the agents' utility functions: prosumer Eq. (7) '|Y_Ri|+|Y_Fi|-|Z_Ri|-|Z_Fi| >= d_ri', supplier Eq. (10) '|Y_Ri|+|Y_Fi| >= |Z_Ri|+|Z_Fi|', generator Eq. (12) 'gbar_i >= |Z_Ri|+|Z_Fi|-|Y_Ri|-|Y_Fi| >= 0'. These inequalities are literally present in the source, so formalization_origin=source. C001 is the general cross-agent umbrella statement; the source gives no single symbolic form for a generic agent (the balance is instantiated per agent type in C002-C004), so it is left not_formalized with expression=null. Variables Y_Fi, Y_Ri, Z_Fi, Z_Ri (selected bought/sold contract sets) and parameters d_ri (prosumer net demand) and gbar_i (generator capacity) are declared from the source nomenclature and per-agent definitions and bound to the single existing node execution.energy_trade; E is empty so no edge bindings are possible. IMPORTANT: all B evidence used here remains UNREVIEWED (source_status=unverified) under this experiment's source_review_policy; the transcriptions are provisional candidate support and must not be treated as source-audited or scientifically accepted. Sign, index and quantifier conventions (agent sets P, S, G; markets R and F) are kept as printed; unresolved rendering ambiguities noted in the B catalog (e.g. overline on d_fi, missing subscript in Eq. (16)) do not affect the transcribed balance inequalities.","bindings":[{"object_id":"v141-c-R003-x-YFi","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Operand of the energy-balance relation governed by the approved function node execution.energy_trade; this is the only node in the frozen graph (E is empty), and |Y_{Fi}| appears in the balance obligations of C002-C004."},{"object_id":"v141-c-R003-x-YRi","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Operand of the energy-balance relation governed by the approved function node execution.energy_trade; |Y_{Ri}| appears in the balance obligations of C002-C004."},{"object_id":"v141-c-R003-x-ZFi","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Operand of the energy-balance relation governed by the approved function node execution.energy_trade; |Z_{Fi}| appears in the balance obligations of C002-C004."},{"object_id":"v141-c-R003-x-ZRi","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Operand of the energy-balance relation governed by the approved function node execution.energy_trade; |Z_{Ri}| appears in the balance obligations of C002-C004."},{"object_id":"v141-c-R003-T001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Prosumer net-demand constant entering the prosumer energy-balance obligation (C002) owned by execution.energy_trade."},{"object_id":"v141-c-R003-T002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Generator capacity constant entering the generator energy-balance obligation (C004) owned by execution.energy_trade."},{"object_id":"v141-c-R003-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formalized prosumer balance obligation is an attribute of the execution.energy_trade node; no edge exists in the frozen graph to bind (E empty)."},{"object_id":"v141-c-R003-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formalized supplier balance obligation is an attribute of the execution.energy_trade node; no edge exists in the frozen graph to bind (E empty)."},{"object_id":"v141-c-R003-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Formalized generator balance obligation is an attribute of the execution.energy_trade node; no edge exists in the frozen graph to bind (E empty)."}],"revision_requests":["The frozen graph is flat (V={execution.energy_trade}, E={}); all four balance obligations attach to the single approved-function node. No graph revision is strictly required to carry the transcribed inequalities, but C.1 may optionally add quantity/role objects (agent-type sets P, S, G; upstream/downstream contract quantities |Y_mi|, |Z_mi|; generation/load terms) and edges to execution.energy_trade so the balance relations are explicit at graph level.","Constraint C001 (general cross-agent statement) has no single source symbolic form: the source instantiates the energy balance separately per agent type (prosumer Eq. (7), supplier Eq. (10), generator Eq. (12)). It is therefore left not_formalized; if C.1 intends a generic quantifier form, the graph would need a generic generation/load symbol that the source does not define.","All support used here is UNREVIEWED candidate B evidence; the balance inequalities are transcribed from the finite-domain conditions of Eqs. (7), (10) and (12) and should be re-checked against the page images (sign, subscript and overline rendering) before being treated as source-verified."]}},"quarantined_references":[]}});
